<script setup>
import {ref,onMounted} from 'vue';import {api,mutate,session,notify} from '../lib/api.js';import {settingsSchema} from '../../shared/contracts.js';import {eurosToCents} from '../../shared/money.js';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import AccountSecurity from '../components/AccountSecurity.vue';
const form=ref(null),error=ref(''),busy=ref(false),password=ref({current:'',password:'',confirm:''}),logo=ref(null);
const twofa=ref({setup:null,code:'',password:'',busy:false});
async function startTotp(){twofa.value.busy=true;try{twofa.value.setup=await api('/auth/2fa/setup',{method:'POST'});}catch(e){notify(e.message,'error');}finally{twofa.value.busy=false;}}
async function enableTotp(){twofa.value.busy=true;try{await api('/auth/2fa/enable',{method:'POST',body:{token:twofa.value.code}});session.user.totpEnabled=true;twofa.value.setup=null;twofa.value.code='';notify('Double authentification activée.');}catch(e){notify(e.message,'error');}finally{twofa.value.busy=false;}}
async function disableTotp(){twofa.value.busy=true;try{await api('/auth/2fa/disable',{method:'POST',body:{password:twofa.value.password,token:twofa.value.code}});session.user.totpEnabled=false;twofa.value.password='';twofa.value.code='';notify('Double authentification désactivée.');}catch(e){notify(e.message,'error');}finally{twofa.value.busy=false;}}
onMounted(async()=>{try{const data=await api('/settings');form.value={...data,deposit:String(data.depositBps/100)};}catch(e){error.value=e.message;}});
async function save(){busy.value=true;error.value='';try{if(logo.value){const body=new FormData();body.append('file',logo.value);const doc=await api('/documents',{method:'POST',body});form.value.logoDocumentId=doc.id;logo.value=null;}const data=settingsSchema.parse({...form.value,depositBps:eurosToCents(form.value.deposit)});await mutate('/settings','PUT',data,'Paramètres enregistrés.');}catch(e){error.value=e.issues?e.issues.map(i=>i.message).join(' · '):e.message;}finally{busy.value=false;}}
async function changePassword(){try{if(password.value.password!==password.value.confirm)throw new Error('Les mots de passe ne correspondent pas.');await api('/auth/password',{method:'POST',body:password.value});session.user=null;session.csrf='';notify('Mot de passe modifié. Reconnectez-vous.');}catch(e){notify(e.message,'error');}}
</script>
<template><PageTitle number="11" title="LES PARAMÈTRES" subtitle="Votre studio, dans les moindres détails."><button class="btn primary" :disabled="busy||!form" @click="save">{{busy?'Enregistrement…':'Enregistrer'}}<Icon name="Check"/></button></PageTitle><p v-if="error" class="form-error" style="margin-bottom:22px">{{error}}</p><form v-if="form" @submit.prevent="save"><div class="settings-grid"><section class="builder-section"><span class="eyebrow">01 / IDENTITÉ</span><h2>L’ENTREPRISE.</h2><div class="form-grid"><label class="span-2">Nom commercial<input v-model="form.name" required></label><label class="span-2">Nom de l’entrepreneur<input v-model="form.owner"></label><label class="span-2">Adresse complète<textarea v-model="form.address" placeholder="À compléter avant émission d’une facture"/></label><label>Email<input v-model="form.email" type="email" required></label><label>Téléphone<input v-model="form.phone" type="tel"></label><label class="span-2">SIRET<input v-model="form.siret" maxlength="14" inputmode="numeric" placeholder="14 chiffres"></label><label class="span-2">IBAN<input v-model="form.iban" placeholder="FR…"></label><label class="span-2">Logo (PNG ou JPG)<input type="file" accept="image/png,image/jpeg" @change="logo=$event.target.files[0]"></label><div class="span-2" v-if="form.logoDocumentId"><img :src="`/api/documents/${form.logoDocumentId}/image`" alt="Logo de l’entreprise" style="max-width:160px;max-height:90px"><button class="text-button" type="button" @click="form.logoDocumentId=''">Retirer le logo</button></div></div></section><section class="builder-section"><span class="eyebrow">02 / DEVIS</span><h2>LE CADRE COMMERCIAL.</h2><div class="form-grid"><label>Validité (jours)<input type="number" min="1" max="365" v-model.number="form.validDays" required></label><label>Acompte par défaut (%)<input v-model="form.deposit" inputmode="decimal" required></label><label class="span-2">Conditions de paiement<textarea v-model="form.conditions" rows="5"/></label></div></section><section class="builder-section"><span class="eyebrow">03 / FACTURATION</span><h2>LES DOCUMENTS.</h2><label>Préfixe des factures<input v-model="form.invoicePrefix" required pattern="[A-Z]{2,8}" maxlength="8"></label><p class="field-note" style="margin:10px 0 20px">Le compteur progresse automatiquement par année à l’émission. Exemple : {{form.invoicePrefix}}-{{new Date().getFullYear()}}-001.</p><label>Mentions légales<textarea v-model="form.legalNotice" rows="5"/></label><label style="display:block;margin-top:16px">Mentions B2B — pénalités de retard<textarea v-model="form.latePaymentNotice" rows="4"/></label><p class="field-note" style="margin-top:8px">Imprimées uniquement sur les devis et factures dont la case « client professionnel » est cochée.</p><p class="field-note" style="margin-top:12px">Ces paramètres s’appliquent aux nouveaux documents. Les documents émis conservent leurs informations historiques.</p></section></div></form><section class="builder-section" style="margin-top:24px;max-width:650px"><span class="eyebrow">04 / SÉCURITÉ</span><h2>L’ACCÈS AU STUDIO.</h2><AccountSecurity/></section></template>
